mapper.select:
select tc.id as courierId, count(tcto.trade_no) as total from tb_courier tc left join tb_courier_trade_order tcto on tc.id = tcto.courier_id and tcto.trade_create_time > concat(#{today}, ' 00:00:00') and tcto.trade_create_time < concat(#{today}, ' 23:59:59')
#{id}
group by tc.id

select tc.id, count(tcto.trade_no) from tb_courier tc left join tb_courier_trade_order tcto on tc.id = tcto.courier_id and tcto.trade_create_time < concat(#{today}, ' 23:59:59') and tcto.trade_create_time > concat(#{today}, ' 00:00:00') and tcto.waybill_status in (3, 4)
#{id}
group by tc.id having count(tcto.trade_no) < 12
